import unicodedata
def compte_voyelles(s):
 n = unicodedata.normalize('NFD', s.lower())
 return sum(1 for c in n if c in 'aeiou')

def puissance_rapide(b, e): 
 r, p = 1, b
 while e:
  if e & 1: r *= p
  p *= p; e >>= 1
 return r

import itertools
def compresse(s):
 return ''.join(f'{c}{len(list(g))}' for c, g in itertools.groupby(s))

def indices_somme(lst, cible): 
 vus = {}
 for i, v in enumerate(lst):
  if cible - v in vus: return (vus[cible-v], i)
  vus[v] = i
 return None

