import re
def camel_vers_snake(s):
 return re.sub(r'(?<!^)(?=[A-Z])', '_', s).lower()

def valide_parentheses(s):
 p = {')':'(', ']':'[', '}':'{'}; pile = []
 for c in s:
  if c in '([{': pile.append(c)
  elif c in p:
   if not pile or pile.pop() != p[c]: return False
 return not pile

def distance_levenshtein(a, b):
 m, n = len(a), len(b)
 prev = list(range(n+1))
 for i in range(1, m+1):
  cur = [i] + [0]*n
  for j in range(1, n+1):
   cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1] + (a[i-1] != b[j-1]))
  prev = cur
 return prev[n]
